    "role.bar.practitioner": "Praticien·ne",
    "role.label": "Bienvenue",
    "role.title": "À qui est-ce destiné ?",
    "role.sub": "Choisissez la perspective qui correspond à votre besoin actuel. Vous pouvez changer à tout moment avec le sélecteur dans le coin.",
    "role.part.sub": "Explorer la TBF",
    "role.part.title": "J'explore la thérapie basée sur la forêt",
    "role.part.desc": "Informations en langage clair sur ce qu'est la TBF, le déroulement des séances, et si elle peut être utile pour votre situation ou celle d'un proche.",
    "role.part.eg": "Participant·e · proche · orienteur·se · personne curieuse",
